def pd(q, qd, q_target, I=0.04, wn=8.0, zeta=0.85):
    kp = I * wn ** 2
    kd = 2 * zeta * I * wn
    tau = kp * (q_target - q) - kd * qd
    return np.clip(tau, -6.0, 6.0)

import gymnasium as gym
import mujoco
import numpy as np

class CartpoleEnv(gym.Env):
    def __init__(self):
        self.model = mujoco.MjModel.from_xml_path("cartpole.xml")
        self.data = mujoco.MjData(self.model)
        self.action_space = gym.spaces.Box(-1, 1, (1,))

    def step(self, action):
        self.data.ctrl[:] = action * 20
        for _ in range(5):
            mujoco.mj_step(self.model, self.data)
        return self._obs(), self._reward(), False, False, {}
